/* IRON GRID 2D - central asset loader (manifest: static/assets/2d/manifest.json, generated by tools/gen_2d_assets.py).
 * Lazy, cached, failure-tolerant: a missing or broken file is remembered and the renderer uses its procedural drawing.
 * Supported manifest entry fields (all optional except "file"):
 *   file        path under assets/2d/            variants  N -> files name_0.png ... name_{N-1}.png (terrain)
 *   frames      frames in a horizontal sheet     frame_ms  duration of one frame at 100% speed
 *   loop        repeat the sheet                 fw / fh   frame size in px (default: image width/frames, image height)
 *   scale       draw-size multiplier             rotate    (effects) turn the image toward its direction of travel
 *   anchor      [x, y] 0..1 origin inside the frame (default centre)
 * Sprites are authored at manifest.px_per_tile (default 128) pixels per board tile, so images need not be tile-sized. */
(function (G) {
  "use strict";
  const Assets2D = {
    manifest: null, base: "", cache: new Map(), failed: new Set(), pending: new Set(), onLoad: null, _ready: null, ppt: 128,
    init() {
      if (this._ready) return this._ready;
      this.base = G.GFX_BASE + "assets/2d/";
      this._ready = fetch(this.base + "manifest.json", { cache: "no-cache" }).then(r => (r.ok ? r.json() : {})).catch(() => ({}))
        .then(m => { this.manifest = m || {}; this.ppt = this.manifest.px_per_tile || 128; return this; });
      return this._ready;
    },
    entry(kind, id) { return (this.manifest && this.manifest[kind] && this.manifest[kind][id]) || null; },
    meta(kind, id) { return this.entry(kind, id); },
    _file(e, variant) {
      if (e.variants > 1 && variant != null) return e.file.replace(/(\.[a-z0-9]+)$/i, `_${variant % e.variants}$1`);
      return e.file;
    },
    /** Loaded Image or null (not loaded yet / missing / not in manifest). Never throws, never reloads a failure. */
    img(kind, id, variant) {
      const e = this.entry(kind, id);
      if (!e || !e.file) return null;
      const file = this._file(e, variant), key = file, hit = this.cache.get(key);
      if (hit) return hit;
      if (this.failed.has(key) || this.pending.has(key)) return null;
      const im = new Image(); this.pending.add(key);
      im.onload = () => { this.pending.delete(key); this.cache.set(key, im); if (this.onLoad) this.onLoad(); };
      im.onerror = () => { this.pending.delete(key); this.failed.add(key); };
      im.src = this.base + file;
      return null;
    },
    /** Current frame of a sprite sheet: {img, sx, sy, sw, sh, e} or null. Missing frames clamp to the last available one. */
    frame(kind, id, elapsedMs, variant) {
      const e = this.entry(kind, id), im = e && this.img(kind, id, variant);
      if (!im) return null;
      const n = Math.max(1, e.frames | 0), sw = e.fw || Math.floor(im.width / n), sh = e.fh || im.height;
      const avail = Math.max(1, Math.min(n, Math.floor(im.width / Math.max(1, sw))));         // frames actually present in the image
      const fd = Math.max(1, G.anim.dur(e.frame_ms || 60));
      let i = Math.floor(Math.max(0, elapsedMs) / fd);
      i = e.loop ? i % avail : Math.min(i, avail - 1);
      return { img: im, sx: i * sw, sy: 0, sw, sh, e };
    },
    /** Duration (ms at the current speed) of an animated entry, or 0 when it is not animated. */
    duration(kind, id) { const e = this.entry(kind, id); return e && e.frames > 1 ? G.anim.dur(e.frame_ms || 60) * e.frames : 0; },
    clear() { this.cache.clear(); this.failed.clear(); this.pending.clear(); },
  };
  G.Assets2D = Assets2D;
})(window.GFX = window.GFX || {});
